from pymongo import MongoClient
from pymongo.uri_parser import parse_uri

from app.settings import require_env

_client: MongoClient | None = None


def _get_client() -> MongoClient:
    global _client
    if _client is None:
        _client = MongoClient(
            require_env("MONGODB_URL"),
            maxPoolSize=50,
            minPoolSize=1,
            serverSelectionTimeoutMS=5000,
        )
    return _client


def get_database_name() -> str:
    database = parse_uri(require_env("MONGODB_URL")).get("database")
    if not database:
        raise RuntimeError("MONGODB_URL must include a database name")
    return database


def get_db():
    return _get_client()[get_database_name()]


def close_client() -> None:
    global _client
    if _client is not None:
        _client.close()
        _client = None

