import hashlib
import hmac
import json
import logging
import re
import traceback

from fastapi import APIRouter, BackgroundTasks, Header, HTTPException, Request

from app.logs.db_logger import write_log
from app.sessions import service
from app.settings import get_env

logger = logging.getLogger(__name__)

router = APIRouter(prefix="/webhooks", tags=["webhooks"])

MENTION_RE = re.compile(r"@([A-Za-z0-9-]+)")


def _verify_signature(payload: bytes, signature: str | None) -> bool:
    secret = [secret redacted]
    if not secret or not signature:
        [secret redacted]
    expected = "sha256=" + hmac.new(secret.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)


def _agent_user() -> str:
    return get_env("AGENT_USER") or "test-bot"


def _handle_issues_assigned(payload: dict) -> None:
    repo = payload["repository"]["full_name"]
    issue = payload["issue"]
    session_id = service.create_or_get_session(repo, issue["number"])
    service.update_issue_info(session_id, issue.get("title", ""), issue.get("body") or "")
    write_log(
        {
            "session_id": session_id,
            "level": "info",
            "source": "webhooks.github",
            "message": f"issues.assigned for {repo}#{issue['number']}",
        }
    )


def _handle_issue_comment(payload: dict) -> None:
    repo = payload["repository"]["full_name"]
    issue = payload["issue"]
    comment = payload.get("comment") or {}
    body = comment.get("body") or ""
    author = [secret redacted]
    session_id = service.create_or_get_session(repo, issue["number"])
    service.append_comment(session_id, body, author)
    mentions = MENTION_RE.findall(body)
    if _agent_user() in mentions:
        write_log(
            {
                "session_id": session_id,
                "level": "info",
                "source": "webhooks.github",
                "message": f"agent mentioned by {author} on {repo}#{issue['number']}",
            }
        )


def process_event(event: str, payload: dict) -> None:
    write_log(
        {"level": "info", "source": "webhooks.github", "message": f"webhook received: {event}"}
    )
    try:
        if event == "issues.assigned":
            _handle_issues_assigned(payload)
        elif event == "issue_comment.created":
            _handle_issue_comment(payload)
        else:
            logger.info("Unhandled webhook event: %s", event)
    except Exception:
        write_log(
            {
                "level": "error",
                "source": "webhooks.github",
                "message": f"failed processing {event}: {traceback.format_exc()}",
            }
        )


@router.post("/github")
async def github_webhook(
    request: Request,
    background_tasks: BackgroundTasks,
    x_github_event: str = Header(default=""),
    x_hub_signature_256: str = Header(default=None),
):
    body = await request.body()
    if not _verify_signature(body, x_hub_signature_256):
        raise HTTPException(status_code=401, detail="Invalid signature")
    try:
        payload = json.loads(body) if body else {}
    except json.JSONDecodeError as exc:
        raise HTTPException(status_code=400, detail=f"Malformed JSON: {exc}")
    logger.info("GitHub webhook received: %s", x_github_event)
    if x_github_event == "ping":
        return {"status": "ok", "event": "ping"}
    background_tasks.add_task(process_event, x_github_event, payload)
    return {"status": "ok", "event": x_github_event}
